interface EmailNotice { recipient: string; templateId: string; variables: Record<string, string>; }

class NoticeController {
  constructor(private repo: NoticeRepo, private queue: DeliveryQueue) {}

  async submit(input: EmailNotice) {
    if (!input.recipient || !input.templateId) throw new Error('recipient and templateId are required');
    const notice = await this.repo.insert({
      recipient: input.recipient,
      templateId: input.templateId,
      variables: input.variables,
      status: 'queued'
    });
    await this.queue.add({ noticeId: notice.id });
    return { noticeId: notice.id };
  }
}

class EmailDeliveryWorker {
  constructor(
    private repo: NoticeRepo,
    private renderer: TemplateRenderer,
    private mailer: EmailGateway,
    private events: EventBus
  ) {}

  async handle(job: { noticeId: string }) {
    const notice = await this.repo.get(job.noticeId);
    const content = await this.renderer.render(notice.templateId, notice.variables);
    await this.repo.setStatus(notice.id, 'sending');
    const result = await this.mailer.send({
      to: notice.recipient,
      subject: content.subject,
      text: content.text
    });
    const status = result.accepted ? 'sent' : 'failed';
    await this.repo.setStatus(notice.id, status);
    await this.events.publish({
      type: 'notice.status',
      noticeId: notice.id,
      status,
      providerMessageId: result.messageId
    });
  }
}

class StatusCallbackHandler {
  constructor(private sink: CallbackSink) {}

  async handle(event: { type: string; noticeId: string; status: string; providerMessageId: string }) {
    if (event.type !== 'notice.status') return;
    await this.sink.notify({
      noticeId: event.noticeId,
      status: event.status,
      providerMessageId: event.providerMessageId
    });
  }
}
